function loadConditionals(){
  var frame = document.getElementById("conditionalsFrame");
  if(!frame || frame.dataset.loaded) return;
  var bin = atob(CONDITIONALSEMBED);
  var bytes = new Uint8Array(bin.length);
  for(var i=0;i<bin.length;i++) bytes[i] = bin.charCodeAt(i);
  var htmlStr;
  try {
    htmlStr = new TextDecoder("utf-8").decode(bytes);
  } catch(e) {
    htmlStr = decodeURIComponent(escape(bin));
  }
  var tempEdits = JSON.parse(JSON.stringify(USER_EDITS));
  if(tempEdits.cond_study && (!Array.isArray(tempEdits.cond_study) || tempEdits.cond_study.length === 0 || (tempEdits.cond_study[0] && !tempEdits.cond_study[0].type && !tempEdits.cond_study[0].title))) delete tempEdits.cond_study;
  if(tempEdits.cond_quiz && (!Array.isArray(tempEdits.cond_quiz) || tempEdits.cond_quiz.length === 0 || (tempEdits.cond_quiz[0] && !tempEdits.cond_quiz[0].type && !tempEdits.cond_quiz[0].cond))) delete tempEdits.cond_quiz;
  var editsStr = JSON.stringify(tempEdits).replace(/</g, '\\u003c');
  var inject = "<script>window.PARENT_EDITS = " + editsStr + ";<\/script>";
  htmlStr = htmlStr.replace("</head>", inject + "</head>");
  frame.srcdoc = htmlStr;
  frame.dataset.loaded = "1";
}
function mojibakeCleanerScript(){return `<script>
(function(){
  var busy=false;
  var pairs=[
    ['Ã¡','á'],['Ã©','é'],['Ã­','í'],['Ã³','ó'],['Ãº','ú'],['Ã±','ñ'],['Ã¼','ü'],
    ['Ã','Á'],['Ã‰','É'],['Ã','Í'],['Ã“','Ó'],['Ãš','Ú'],['Ã‘','Ñ'],['Ãœ','Ü'],
    ['Â¿','¿'],['Â¡','¡'],['Âº','º'],['Âª','ª'],['Â°C','°C'],['Â·','·'],['Â«','«'],['Â»','»'],['Â',''],
    ['âŒ‚',''],['â†’','→'],['â†','←'],['â€”','—'],['â€“','–'],['â€¦','…'],['â€¢','•'],
    ['âœ“','✓'],['âœ”','✓'],['âœ…','✓'],['âœ—','✗'],['âŒ','✗'],['â˜…','★']
  ];
  function fix(s){
    if(!s) return s;
    for(var i=0;i<pairs.length;i++) s=s.split(pairs[i][0]).join(pairs[i][1]);
    s=s.replace(/ðŸ[^\\s<]*/g,'').replace(/�/g,'');
    return s.replace(/^\\s+Inicio\\b/,'Inicio').replace(/\\s{2,}/g,' ');
  }
  function cleanNode(n){
    if(n.nodeType===3){var v=fix(n.nodeValue); if(v!==n.nodeValue)n.nodeValue=v; return;}
    if(n.nodeType!==1) return;
    ['title','placeholder','aria-label','value'].forEach(function(a){
      if(n.hasAttribute&&n.hasAttribute(a)){
        var before=n.getAttribute(a), after=fix(before);
        if(after!==before)n.setAttribute(a,after);
      }
    });
    for(var c=n.firstChild;c;c=c.nextSibling) cleanNode(c);
  }
  function clean(){if(busy)return; busy=true; cleanNode(document.body); busy=false;}
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',clean); else clean();
  new MutationObserver(clean).observe(document.documentElement,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['title','placeholder','aria-label','value']});
})();
<\/script>`}
function injectMojibakeCleaner(html){
  var cleaner = mojibakeCleanerScript();
  if(html.indexOf('mojibakeCleanerScript')>=0) return html;
  if(/<\/body>/i.test(html)) return html.replace(/<\/body>/i, cleaner + '<\/body>');
  return html + cleaner;
}
function loadEmbeddedHtml(frameId, payload){
  var frame = document.getElementById(frameId);
  if(!frame || frame.dataset.loaded) return;
  var bin = atob(payload);
  var bytes = new Uint8Array(bin.length);
  for(var i=0;i<bin.length;i++) bytes[i] = bin.charCodeAt(i);
  var htmlStr;
  try {
    htmlStr = new TextDecoder("utf-8").decode(bytes);
  } catch(e) {
    htmlStr = decodeURIComponent(escape(bin));
  }
  frame.srcdoc = injectMojibakeCleaner(htmlStr);
  frame.dataset.loaded = "1";
}
function loadVerbTenses(){loadEmbeddedHtml("verbTensesFrame", VERBTENSESEMBED)}

